SELECT id, product_id, revenue, MAX(units) OVER (PARTITION BY product_id) AS product_id_max_units, LAST_VALUE(revenue, TRUE) OVER (ORDER BY sale_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_revenue, SUM(units) OVER (PARTITION BY store_id ORDER BY units, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_units, ROW_NUMBER() OVER (ORDER BY sale_date, id) AS row_seq FROM store_sales
